import{_ as p,a0 as r,w as o,s as d,ao as l,I as n,x as s,a1 as i,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"基于 FUSE 的 Bittorrent 文件系统 | LCTT x X-CMD","titleTemplate":false,"description":"基于 FUSE 的 Bittorrent 文件系统 | LCTT (201806) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"基于 FUSE 的 Bittorrent 文件系统 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"基于 FUSE 的 Bittorrent 文件系统 | LCTT (201806) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201806/20180525 A Bittorrent Filesystem Based On FUSE","title":"基于 FUSE 的 Bittorrent 文件系统","tag":"201806","desc":""},"relativePath":"201806/20180525 A Bittorrent Filesystem Based On FUSE.md","filePath":"[post].md"}'),h={name:"201806/20180525 A Bittorrent Filesystem Based On FUSE.md"};function g(b,t,k,u,c,f){const e=r("Link");return o(),d("div",null,[t[18]||(t[18]=l('<h1 id="基于-fuse-的-bittorrent-文件系统" tabindex="-1">基于 FUSE 的 Bittorrent 文件系统 <a class="header-anchor" href="#基于-fuse-的-bittorrent-文件系统" aria-label="Permalink to “基于 FUSE 的 Bittorrent 文件系统”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/05/Bittorrent-720x340.png" alt=""></p><p>Bittorrent 已经存在了很长时间，它可以从互联网上共享和下载数据。市场上有大量的 GUI 和 CLI 的 Bittorrent 客户端。有时，你不能坐下来等待你的下载完成。你可能想要立即观看内容。这就是 <strong>BTFS</strong> 这个不起眼的文件系统派上用场的地方。使用 BTFS，你可以将种子文件或磁力链接挂载为目录，然后在文件树中作为只读目录。这些文件的内容将在程序读取时按需下载。由于 BTFS 在 FUSE 之上运行，因此不需要干预 Linux 内核。</p><h3 id="安装-btfs" tabindex="-1">安装 BTFS <a class="header-anchor" href="#安装-btfs" aria-label="Permalink to “安装 BTFS”">​</a></h3><p>BTFS 存在于大多数 Linux 发行版的默认仓库中。</p><p>在 Arch Linux 及其变体上，运行以下命令来安装 BTFS。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S btfs</span></span></code></pre></div><p>在Debian、Ubuntu、Linux Mint 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install btfs</span></span></code></pre></div><p>在 Gentoo 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># emerge -av btfs</span></span></code></pre></div>',11)),n("p",null,[t[1]||(t[1]=s("BTFS 也可以使用 ",-1)),i(e,{href:"https://www.ostechnix.com/linuxbrew-common-package-manager-linux-mac-os-x/"},{default:a(()=>[...t[0]||(t[0]=[s("Linuxbrew",-1)])]),_:1}),t[2]||(t[2]=s(" 包管理器进行安装。",-1))]),t[19]||(t[19]=l('<div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ brew install btfs</span></span></code></pre></div><h3 id="用法" tabindex="-1">用法 <a class="header-anchor" href="#用法" aria-label="Permalink to “用法”">​</a></h3><p>BTFS 的使用非常简单。你所要做的就是找到 .torrent 文件或磁力链接，并将其挂载到一个目录中。种子文件或磁力链接的内容将被挂载到你选择的目录内。当一个程序试图访问该文件进行读取时，实际的数据将按需下载。此外，像 <code>ls</code> 、<code>cat</code> 和 <code>cp</code> 这样的工具能按照预期的方式来操作种子。像 <code>vlc</code> 和 <code>mplayer</code> 这样的程序也可以不加修改地工作。玩家甚至不知道实际内容并非物理存在于本地磁盘中，而是根据需要从 peer 中收集。</p><p>创建一个目录来挂载 torrent/magnet 链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ mkdir mnt</span></span></code></pre></div><p>挂载 torrent/magnet 链接：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ btfs video.torrent mnt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/btfs.png" alt=""></p><p>cd 到目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd mnt</span></span></code></pre></div><p>然后，开始观看！</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vlc &lt;path-to-video.mp4&gt;</span></span></code></pre></div><p>给 BTFS 一些时间来找到并获取网站 tracker。一旦加载了真实数据，BTFS 将不再需要 tracker。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/05/btfs-1.png" alt=""></p><p>要卸载 BTFS 文件系统，只需运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ fusermount -u mnt</span></span></code></pre></div><p>现在，挂载目录中的内容将消失。要再次访问内容，你需要按照上面的描述挂载 torrent。</p><p>BTFS 会将你的 VLC 或 Mplayer 变成爆米花时间。挂载你最喜爱的电视节目或电影的种子文件或磁力链接，然后开始观看，无需下载整个种子内容或等待下载完成。种子或磁力链接的内容将在程序访问时按需下载。</p><p>就是这些了。希望这些有用。还会有更好的东西。敬请关注！</p><p>干杯！</p><hr>',21)),n("p",null,[t[4]||(t[4]=s("via: ",-1)),i(e,{href:"https://www.ostechnix.com/btfs-a-bittorrent-filesystem-based-on-fuse/"},{default:a(()=>[...t[3]||(t[3]=[s("https://www.ostechnix.com/btfs-a-bittorrent-filesystem-based-on-fuse/",-1)])]),_:1})]),n("p",null,[t[9]||(t[9]=s("作者：",-1)),i(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...t[5]||(t[5]=[s("SK",-1)])]),_:1}),t[10]||(t[10]=s(" 选题：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[6]||(t[6]=[s("lujun9972",-1)])]),_:1}),t[11]||(t[11]=s(" 译者：",-1)),i(e,{href:"https://github.com/geekpi"},{default:a(()=>[...t[7]||(t[7]=[s("geekpi",-1)])]),_:1}),t[12]||(t[12]=s(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:a(()=>[...t[8]||(t[8]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[15]||(t[15]=s("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[13]||(t[13]=[s("LCTT",-1)])]),_:1}),t[16]||(t[16]=s(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:a(()=>[...t[14]||(t[14]=[s("Linux中国",-1)])]),_:1}),t[17]||(t[17]=s(" 荣誉推出",-1))])])}const C=p(h,[["render",g]]);export{x as __pageData,C as default};
